INSERT INTO authors (id, name, bio) VALUES
  ('andrei-popescu', 'Andrei Popescu', 'Andrei Popescu is a productivity coach who has spent fifteen years helping teams and students work with intention. His writing turns research on attention into simple daily habits.'),
  ('radu-ionescu', 'Radu Ionescu', 'Radu Ionescu is an educator and learning-science writer. He explores how curiosity, practice and feedback turn beginners into experts.'),
  ('james-wright', 'James Wright', 'James Wright is a former executive turned mentor. His books distil lessons from decades of leading start-ups through growth and failure.'),
  ('james-adams', 'James Adams', 'James Adams writes dark, fast-paced thrillers set in quiet towns where nothing is quite what it seems.'),
  ('jessica-martin', 'Jessica Martin', 'Jessica Martin is a bestselling romance novelist known for sweeping, emotional stories about second chances.'),
  ('laura-mitchell', 'Laura Mitchell', 'Laura Mitchell is a former aerospace engineer who writes science fiction grounded in real physics and very human stakes.'),
  ('daniel-reed', 'Daniel Reed', 'Daniel Reed is a minimalism advocate and writer. After leaving a corporate career he began writing about living with less, and found far more peace, clarity and joy in doing so.'),
  ('clara-nelson', 'Clara Nelson', 'Clara Nelson writes gothic mysteries and ghost stories inspired by the old houses of her childhood.'),
  ('emily-parker', 'Emily Parker', 'Emily Parker is an award-winning children''s author and illustrator whose gentle stories are loved by readers of all ages.'),
  ('mara-stoica', 'Mara Stoica', 'Mara Stoica is a poet, travel writer and cook. Her work celebrates food, memory and the journeys in between.'),
  ('omar-haddad', 'Omar Haddad', 'Omar Haddad is a historian and biographer who brings forgotten figures and distant eras vividly to life.'),
  ('sofia-rossi', 'Sofia Rossi', 'Sofia Rossi writes young-adult fiction, comics and stage plays about growing up and finding your voice.'),
  ('henry-cole', 'Henry Cole', 'Henry Cole is a science communicator and philosopher who makes big ideas feel approachable.'),
  ('ioana-marin', 'Ioana Marin', 'Ioana Marin is a linguist and teacher who designs story-based methods for learning new languages quickly.');
